"""Turn a compiled .spv into a C header of uint32 words (build-time tool)."""

import struct, sys
from pathlib import Path

src, dst = map(Path, sys.argv[1:3])
data = src.read_bytes()
words = struct.unpack(f"<{len(data)//4}I", data[: len(data) // 4 * 4])
name = src.stem.replace("-", "_")
out = [
  "/* Generated by tools/spv_to_header.py; do not edit. */",
  "#ifndef BITSY_SPV_" + name.upper() + "_H",
  "#define BITSY_SPV_" + name.upper() + "_H",
  "",
  "#include <stddef.h>",
  "#include <stdint.h>",
  "",
  f"static const uint32_t {name}_spv[] = {{",
  ", ".join(f"0x{w:08x}" for w in words),
  "};",
  f"static const size_t {name}_spv_bytes = sizeof({name}_spv);",
  "",
  "#endif",
  "",
]
dst.parent.mkdir(parents=True, exist_ok=True)
dst.write_text("\n".join(out), encoding="utf-8")
